using System;
using System.Collections.Generic;
using System.Linq;
using UnityEngine;
namespace Workbench {
public static class RuleChecks {
 static Placement P(int id,int type,int x,int y)=>new Placement{id=id,type=type,x=x,y=y};
 static void Assert(bool b,string message){if(!b)throw new Exception(message);}
 public static List<string> Run(GameData d){var passed=new List<string>();Action<string,Action> check=(name,fn)=>{fn();passed.Add(name);};
  check("All ten enemy layouts satisfy construction, power and shield rules",()=>{Assert(d.levels.Length==10,"levels");foreach(var l in d.levels)Assert(Construction.Validate(l.enemy,d,null).Count==0,"Enemy "+l.id+": "+string.Join(",",Construction.Validate(l.enemy,d,null)));});
  check("Area power cost includes chassis and armor",()=>{Assert(d.modules[8].Cost+d.modules[4].Cost==5,"Shield+gun");Assert(d.modules[5].Cost==2,"Rifle");Assert(d.modules[1].Cost==1&&d.modules[2].Cost==1,"Passive");Assert(d.modules[0].Cost==0&&d.modules[3].Cost==0,"Exemptions");});
  check("Exactly one core, legal inventory, no overlap or out-of-bounds",()=>{var l=new List<Placement>{P(0,0,2,2)};Assert(Construction.Validate(l,d,d.levels[0]).Count==0,"Core-only permitted");Assert(Construction.Validate(new List<Placement>(),d,null).Count>0,"No core");l.Add(P(1,0,2,3));Assert(Construction.Validate(l,d,null).Count>0,"Two cores");Assert(!Construction.Fits(P(3,8,4,4),l,d),"2x2 edge");Assert(!Construction.Fits(P(3,8,1,1),l,d),"2x2 overlap");l=new List<Placement>{P(0,0,2,2),P(1,3,1,2),P(2,5,3,2)};Assert(Construction.Validate(l,d,d.levels[0]).Count>0,"Unavailable rifle");});
  check("Side connectivity traverses full modules, diagonal does not",()=>{var l=new List<Placement>{P(0,0,0,0),P(1,3,1,1)};Assert(Construction.Reachable(l,d).Count==1,"Diagonal");l.Add(P(2,8,1,2));Assert(Construction.Reachable(l,d).Count==1,"Disconnected group");l.Add(P(3,1,1,0));Assert(Construction.Reachable(l,d).Count==4,"Reach large module");});
  check("Disconnected multi-part branches detach after link destruction",()=>{var r=new RobotModel(d,new[]{P(0,0,0,0),P(1,1,1,0),P(2,3,2,0),P(3,4,2,1)},0);r.Damage(r.modules[1],999);r.ResolveDamage();Assert(r.Live.Count()==1,"Branch retained");Assert(r.modules[2].detached&&r.modules[3].detached,"Detach reason");});
  check("Disabled connectors preserve HP, mass, collider footprint and graph",()=>{var r=new RobotModel(d,new[]{P(0,0,0,0),P(1,1,1,0),P(2,4,2,0)},0);float mass=r.Mass;r.ResolveDamage();Assert(r.Live.Count()==3&&r.Consumption==0,"Physical parts lost");Assert(r.modules[1].hp==d.modules[1].hp&&r.Mass==mass,"Passive HP/mass changed");});
  check("Power deficit chooses entire modules, random across seeds",()=>{var selected=new HashSet<int>();for(int seed=1;seed<=100;seed++){var r=new RobotModel(d,new[]{P(0,0,1,1),P(1,3,0,1),P(2,3,1,0),P(3,8,2,1),P(4,4,1,2),P(5,1,1,3)},0,seed);r.Damage(r.modules[1],999);r.ResolveDamage();Assert(r.Consumption<=r.Capacity,"Oversupply");Assert(r.modules[3].hp==d.modules[8].hp,"Power changed HP");foreach(var m in r.Live.Where(x=>!x.powered))selected.Add(m.Type);}Assert(selected.Count>1,"No random variety");});
  check("Machinegun round robin and independent rifle rate",()=>{var r=new RobotModel(d,new[]{P(0,0,2,2),P(1,4,1,2),P(2,4,3,2),P(3,5,2,3)},0){firing=true};var shots=new List<Tuple<float,int>>();for(int i=0;i<=180;i++){float t=i/60f;r.Fire(t,m=>shots.Add(Tuple.Create(t,m.Id)));}var a=shots.Where(x=>x.Item2==1).ToArray();var b=shots.Where(x=>x.Item2==2).ToArray();Assert(Mathf.Abs(b[0].Item1-a[0].Item1-.25f)<.02f,"Phase");Assert(Mathf.Abs(a[1].Item1-a[0].Item1-.5f)<.02f,"Gun rate");Assert(shots.Count(x=>x.Item2==3)==2,"Rifle cadence");});
  check("Removing a gun does not reset survivor cooldown",()=>{var r=new RobotModel(d,new[]{P(0,0,2,2),P(1,4,1,2),P(2,4,3,2)},0){firing=true};int count=0;r.Fire(0,m=>count++);r.modules[2].powered=false;r.Fire(.25f,m=>count++);Assert(count==1,"Free shot");r.Fire(.5f,m=>count++);Assert(count==2,"Survivor failed to resume");});
  check("Explosion damages one large module once",()=>{var b=new BattleModel(d,d.levels[5],d.levels[5].enemy,0);var e=b.robots[1];var shield=e.modules.First(m=>m.Type==8);float hp=shield.hp;b.Explode(new ProjectileState{owner=0,position=e.CenterOf(shield),blast=1.8f,damage=7});Assert(Mathf.Abs(shield.hp-(hp-7))<.001f,"Multiple cell damage");});
  check("Reflection swaps owner and velocity, directional arc only",()=>{var b=new BattleModel(d,d.levels[5],d.levels[5].enemy,0);var r=b.robots[0];r.position=new Vector2(20,12);Vector2 center=r.CenterOf(r.Shield);r.aim=center+Vector2.right*10;r.ActivateShield(0);var p=new ProjectileState{owner=1,velocity=Vector2.left*20,position=center+Vector2.right*3};Assert(b.Reflect(p,r,center+Vector2.right*3,center+Vector2.right),"No reflect");Assert(p.owner==0&&p.velocity.x>0&&p.reflected,"Ownership not changed");var q=new ProjectileState{owner=1,velocity=Vector2.right*20};Assert(!b.Reflect(q,r,center-Vector2.right*3,center-Vector2.right),"Shield protects back");Assert(r.ShieldActive(2.99f)&&!r.ShieldActive(3),"Duration");Assert(!r.ActivateShield(29.9f)&&r.ActivateShield(30),"Cooldown");});
  check("Shield immediately ends when its module loses power",()=>{var r=new RobotModel(d,d.levels[5].enemy,0);r.ActivateShield(0);r.Shield.powered=false;r.ResolveDamage();Assert(!r.ShieldActive(1),"Unpowered shield");});
  check("Continuous contact hits once and separation rearms",()=>{var level=new LevelSpec{enemy=new[]{P(0,0,0,0)}};var b=new BattleModel(d,level,new[]{P(0,0,0,0)},0);b.robots[0].position=new Vector2(24.5f,15);b.robots[1].position=new Vector2(26,15);b.robots[0].move=Vector2.right;b.robots[1].move=Vector2.left;for(int i=0;i<120;i++)b.Step(1f/60);Assert(b.impactCount==1,"Contact repeated damage");b.robots[0].position=new Vector2(23,15);b.robots[0].move=b.robots[1].move=Vector2.zero;for(int i=0;i<12;i++)b.Step(1f/60);b.robots[0].position=new Vector2(24.5f,15);b.robots[1].position=new Vector2(26,15);b.robots[0].move=Vector2.right;for(int i=0;i<30;i++)b.Step(1f/60);Assert(b.impactCount==2,"New impact absent");});
  check("Pause freezes simulation, projectiles and star timer",()=>{var b=new BattleModel(d,d.levels[0],d.levels[0].enemy,0);b.robots[0].firing=true;b.Step(.1f);float t=b.time;Vector2 p=b.robots[0].position;int shots=b.projectiles.Count;b.paused=true;b.Step(10);Assert(b.time==t&&b.robots[0].position==p&&b.projectiles.Count==shots,"Pause moved state");});
  check("Time target is not a battle timeout",()=>{var b=new BattleModel(d,d.levels[0],new[]{P(0,0,0,0)},0);for(int i=0;i<100;i++)b.Step(1);Assert(!b.finished&&b.time==100,"Time ended match");});
  check("Stars accumulate, require victory and original build limits",()=>{var a=new RobotModel(d,d.levels[0].enemy,0);var b=new RobotModel(d,d.levels[0].enemy,1);var stars=Stars.Evaluate(d.levels[0],a,b,100,true);Assert(stars[0]&&!stars[1]&&stars[2],"Independent special");var save=new[]{false,true,false,false,false};Stars.Merge(save,stars);Stars.Merge(save,Stars.Evaluate(d.levels[0],a,b,1,false));Assert(save[0]&&save[1]&&save[2],"Lost previous stars");var empty=new RobotModel(d,new[]{P(0,0,0,0)},0);Assert(!Stars.Evaluate(d.levels[0],empty,b,1,true)[3],"Vacuous keep gun");});
  check("No weapon destruction awarded for disabled weapon or core cleanup",()=>{var a=new RobotModel(d,d.levels[1].enemy,0);var b=new RobotModel(d,d.levels[1].enemy,1);foreach(var m in b.modules)m.powered=false;b.Damage(b.Core,999);b.ResolveDamage();Assert(!Stars.Evaluate(d.levels[1],a,b,1,true)[2],"False destruction");});
  check("Compact designs move faster and all arena spawns fit 5x5",()=>{Assert(d.Speed(12)>d.Speed(100)*1.3f,"Mass advantage too small");foreach(var arena in d.arenas){var b=new BattleModel(d,d.levels[9],d.levels[9].enemy,arena.id);foreach(var r in b.robots)Assert(b.ClearAt(r,r.position,true),"Blocked spawn");}});
  check("Ranged bot avoids shotgun range and unarmed bot changes to ram",()=>{var b=new BattleModel(d,d.levels[3],new[]{P(0,0,1,1),P(1,3,0,1),P(2,7,2,1)},0);var ai=new BotController(b,d.levels[3]);ai.Tick();Assert(ai.DesiredRange>=13,"Rifle too close");foreach(var m in b.robots[1].modules)if(m.spec.Weapon)m.powered=false;b.time=2;ai.Tick();Assert(ai.DesiredRange==0,"No ram transition");});
  check("Own modules do not block bullets; enemy armor shields the core",()=>{var level=new LevelSpec{enemy=new[]{P(0,0,2,2),P(1,2,1,2)}};var b=new BattleModel(d,level,new[]{P(0,0,2,2),P(1,3,1,2),P(2,4,0,2)},0);var a=b.robots[0];var e=b.robots[1];a.position=new Vector2(25,14);e.position=new Vector2(35,14);b.projectiles.Add(new ProjectileState{id=81,owner=0,type=4,position=a.CenterOf(a.modules[2]),velocity=Vector2.right*20,remaining=5,range=100,damage=12});for(int i=0;i<50;i++)b.Step(1f/60);Assert(e.modules[1].hp==d.modules[2].hp-12&&e.Core.hp==d.modules[0].hp,"Enemy armor failed to intercept");Assert(a.modules.All(m=>m.hp==m.spec.hp),"Own bullet hit own robot");});
  check("Reflected projectile actually damages its previous owner",()=>{var level=new LevelSpec{enemy=new[]{P(0,0,0,0)}};var b=new BattleModel(d,level,new[]{P(0,0,0,0),P(1,3,1,0),P(2,8,1,1)},0);var r=b.robots[0];r.position=new Vector2(25,12);b.robots[1].position=new Vector2(33,13.5f);Vector2 c=r.CenterOf(r.Shield);r.aim=c+Vector2.right*10;r.ActivateShield(0);var p=new ProjectileState{id=92,owner=1,type=4,velocity=Vector2.left*20,remaining=5,range=100,damage=10};p.trail.Enqueue(c+Vector2.right*3);Assert(b.Reflect(p,r,c+Vector2.right*3,c+Vector2.right),"Reflect missed");Assert(p.trail.Count==0,"Old owner trail retained");b.projectiles.Add(p);for(int i=0;i<30;i++)b.Step(1f/60);Assert(b.robots[1].Core.hp==d.modules[0].hp-10&&r.reflectedHits==1,"Reflected ownership did not reach collision/star logic");});
  check("Builder swaps whole modules without mutating input",()=>{var original=P(2,4,3,2);var list=new List<Placement>{P(0,0,2,2),P(1,3,1,2)};Assert(Construction.TryPlace(list,P(2,4,2,2),original,d,out var swapped),"Exchange rejected");Assert(swapped.Count==3&&swapped.First(p=>p.type==0).x==3&&swapped.First(p=>p.type==4).x==2,"Wrong exchange");Assert(list[0].x==2&&list.Count==2,"Preview changed source");});
  check("Inventory replacement returns every intersected whole module",()=>{var list=new List<Placement>{P(0,0,0,0),P(1,1,1,1),P(2,5,2,1),P(3,3,1,2)};Assert(Construction.TryPlace(list,P(4,8,1,1),null,d,out var replaced),"Replacement rejected");Assert(replaced.Count==2&&replaced.Any(p=>p.type==8)&&!replaced.Any(p=>p.type==5),"Partial module retained");Assert(list.Count==4,"Source inventory lost");});
  check("Impossible different-size swaps fail atomically",()=>{var list=new List<Placement>{P(0,0,3,3),P(1,8,0,0)};Assert(!Construction.TryPlace(list,P(2,1,0,0),P(2,1,4,4),d,out var result)&&result==null,"Large module outside field");Assert(list[1].x==0&&list[1].y==0,"Failed swap mutated original");});
  check("Connectors cover shared cell edges, never diagonals",()=>{var parts=new List<Placement>{P(0,8,0,0),P(1,6,2,0),P(2,0,4,2)};var links=Construction.Links(parts,d).ToArray();Assert(links.Length==2&&links.All(l=>l.horizontal&&l.center.x==2),"Incorrect connector graph");});
  check("Arena edge damage is half impact and sustained contact hits once",()=>{var b=new BattleModel(d,new LevelSpec{enemy=new[]{P(0,0,0,0)}},new[]{P(0,0,0,0)},0);var r=b.robots[0];r.position=new Vector2(.5f,15);r.move=Vector2.left;for(int i=0;i<180;i++)b.Step(1f/60);Assert(b.wallImpactCount==1&&r.Core.hp==d.modules[0].hp-d.balance.impactDamage*.5f,"Edge repeats or wrong damage");r.move=Vector2.right;for(int i=0;i<45;i++)b.Step(1f/60);r.move=Vector2.left;for(int i=0;i<75;i++)b.Step(1f/60);Assert(b.wallImpactCount==2,"Wall contact did not rearm");});
  check("Barrier hits damage one module once",()=>{var b=new BattleModel(d,new LevelSpec{enemy=new[]{P(0,0,0,0)}},new[]{P(0,0,0,0)},0);b.walls[20,15]=true;var r=b.robots[0];r.position=new Vector2(18,15);r.move=Vector2.right;for(int i=0;i<180;i++)b.Step(1f/60);Assert(b.wallImpactCount==1&&r.Core.hp==d.modules[0].hp-7.5f,"Barrier contact");Assert(r.Bounds.xMax<=20.001f,"Crossed barrier");});
  check("Movement accelerates and brakes without changing maximum speed",()=>{var b=new BattleModel(d,d.levels[0],new[]{P(0,0,0,0)},0);var r=b.robots[0];r.position=new Vector2(20,15);r.move=Vector2.right;b.Step(1f/60);Assert(r.velocity.x>0&&r.velocity.x<r.Speed*.5f,"Instant velocity");for(int i=0;i<30;i++)b.Step(1f/60);Assert(Mathf.Abs(r.velocity.x-r.Speed)<.01f,"Wrong maximum speed");r.move=Vector2.zero;for(int i=0;i<30;i++)b.Step(1f/60);Assert(r.velocity.sqrMagnitude<.001f,"Never stops");});
  check("Enemy keeps firing at an active player shield",()=>{var b=new BattleModel(d,d.levels[0],d.levels[5].enemy,0);b.robots[0].position=new Vector2(25,12);b.robots[1].position=new Vector2(35,12);b.robots[0].ActivateShield(0);Assert(b.robots[0].ShieldActive(0),"Test shield");new BotController(b,d.levels[0]).Tick();Assert(b.robots[1].firing,"Bot refuses to shoot shield");});
  passed.AddRange(DrivingChecks.Run(d));return passed;
 }
}
}
